export const editingFormBasedDataControllerExtender = Base => class extends Base {
    init() {
        this._editingController = this.getController("editing");
        super.init()
    }
    _updateEditItem(item) {
        if (this._editingController.isFormEditMode()) {
            item.rowType = "detail"
        }
    }
    getChangedColumnIndices(oldItem, newItem, visibleRowIndex, isLiveUpdate) {
        if (false === isLiveUpdate && newItem.isEditing && this._editingController.isFormEditMode()) {
            return
        }
        return super.getChangedColumnIndices(oldItem, newItem, visibleRowIndex, isLiveUpdate)
    }
};
